import{_ as t,o as n,c as r,a2 as i}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"Der Ausdruckseditor","description":"Token-Ansicht, Werte einfügen, Beispielergebnis — der Dialog „Einen Ausdruck bearbeiten\\".","frontmatter":{"title":"Der Ausdruckseditor","description":"Token-Ansicht, Werte einfügen, Beispielergebnis — der Dialog „Einen Ausdruck bearbeiten\\"."},"headers":[],"relativePath":"apptivescript/editor.md","filePath":"apptivescript/editor.md","lastUpdated":1786613312000}'),d={name:"apptivescript/editor.md"};function s(a,e,o,l,u,c){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="der-ausdruckseditor" tabindex="-1">Der Ausdruckseditor <a class="header-anchor" href="#der-ausdruckseditor" aria-label="Permalink to &quot;Der Ausdruckseditor&quot;">​</a></h1><p>Ausdrücke schreiben Sie nicht in ein leeres Textfeld, sondern in einen Editor, der mitdenkt: Er zeigt Feldnamen statt Ids, führt die passenden Funktionen und rechnet das Ergebnis probeweise aus.</p><h2 id="wo-er-auftaucht" tabindex="-1">Wo er auftaucht <a class="header-anchor" href="#wo-er-auftaucht" aria-label="Permalink to &quot;Wo er auftaucht&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stelle</th><th>So kommen Sie hin</th></tr></thead><tbody><tr><td><strong>Formel</strong>-Spalte</td><td>In den Feldeinstellungen unter <em>Formel</em></td></tr><tr><td><strong>Textfeld eines Flow-Schritts</strong></td><td>Auf einen bereits eingefügten Wert klicken — der Dialog <em>Einen Ausdruck bearbeiten</em> öffnet sich für diesen Baustein</td></tr><tr><td><strong>Flow-Übergang</strong></td><td>Im Dialog <em>Nur fortfahren, wenn …</em> unter <em>Erweiterte Logik</em></td></tr></tbody></table><h2 id="bausteine-oder-text" tabindex="-1">Bausteine oder Text <a class="header-anchor" href="#bausteine-oder-text" aria-label="Permalink to &quot;Bausteine oder Text&quot;">​</a></h2><p>Ein Ausdruck lässt sich in zwei Ansichten bearbeiten. Umgeschaltet wird über das Menü neben der Beschriftung:</p><table tabindex="0"><thead><tr><th>Menüpunkt</th><th>Was Sie sehen</th></tr></thead><tbody><tr><td><strong>Formel mit Text einblenden</strong></td><td>Den Ausdruck als reinen Text — zum Kopieren, Einfügen und für größere Umbauten</td></tr><tr><td><strong>Formel als Token einblenden</strong></td><td>Den Ausdruck als farbige Bausteine — Felder mit ihrem Namen, Funktionen, Werte</td></tr></tbody></table><p>Die Token-Ansicht ist die lesbarere: Statt <code>fieldValue(&#39;64f2a1c0…&#39;)</code> steht dort der Feldname in Blau. Gespeichert wird in beiden Fällen dasselbe.</p><div class="tip custom-block"><p class="custom-block-title">Text-Ansicht für Ausdrücke von woanders</p><p>Einen Ausdruck aus dieser Dokumentation oder aus einem anderen Grid fügen Sie am einfachsten in der Text-Ansicht ein. Anschließend zurück auf Token schalten — gelingt die Umwandlung, war der Ausdruck lesbar.</p></div><h2 id="werte-und-funktionen-einfugen" tabindex="-1">Werte und Funktionen einfügen <a class="header-anchor" href="#werte-und-funktionen-einfugen" aria-label="Permalink to &quot;Werte und Funktionen einfügen&quot;">​</a></h2><p>Unter dem Eingabefeld liegt der Picker mit mehreren Reitern:</p><table tabindex="0"><thead><tr><th>Reiter</th><th>Inhalt</th></tr></thead><tbody><tr><td><strong>Search</strong></td><td>Die Felder des Grids, die Rechenzeichen und die Funktionen des <strong>aktuellen</strong> Typs</td></tr><tr><td><strong>Flow</strong></td><td>Die Ergebnisse der Schritte dieses Flows und die Flow-Variablen</td></tr><tr><td><strong>Date</strong> · <strong>Numbers</strong> · <strong>String</strong> · <strong>Boolean</strong> · <strong>Collection</strong></td><td>Alle Funktionen des jeweiligen Typs, unabhängig vom Ausdruck</td></tr></tbody></table><p>Ein Klick fügt den Eintrag an der Einfügemarke ein. In den Textfeldern eines Flow-Schritts können Sie Werte außerdem aus dem Picker <strong>an die gewünschte Stelle ziehen</strong>.</p><div class="warning custom-block"><p class="custom-block-title">Der Reiter <em>Search</em> ändert sich, während Sie schreiben</p><p>Er zeigt die Funktionen des Typs, den der Ausdruck <strong>gerade</strong> liefert. Nach <code>fieldValue(&#39;titel&#39;)</code> stehen dort Text-Funktionen, nach <code>.isEmpty()</code> die eines Wahrheitswerts. Wer eine Funktion sucht, die dort nicht auftaucht, hat meist den falschen Typ vor sich — nicht die falsche Schreibweise.</p><p>Die Rechenzeichen <code>+ - * /</code> erscheinen nur, wenn der Ausdruck eine Zahl liefert.</p></div><div class="tip custom-block"><p class="custom-block-title">Der Flow-Reiter braucht einen Testlauf</p><p>Die Schrittergebnisse stammen aus dem letzten Testlauf. Ohne ihn bleibt der Reiter leer und der Editor sagt es auch: <em>Zuerst musst du den Flow testen</em>. → <a href="/flows/testen">Flows testen</a></p></div><h2 id="beispielergebnis-und-typ" tabindex="-1">Beispielergebnis und Typ <a class="header-anchor" href="#beispielergebnis-und-typ" aria-label="Permalink to &quot;Beispielergebnis und Typ&quot;">​</a></h2><p>Unter dem Eingabefeld steht <strong>Beispielergebnis</strong> — der Ausdruck, ausgerechnet mit echten Daten: in einer Formelspalte mit einem Eintrag des Grids, in einem Flow mit den Werten des Testlaufs. Darüber steht der ermittelte Typ, etwa <em>Typ: String</em>.</p><p>Der Typ ist die wichtigere der beiden Angaben. Er entscheidet, welche Funktionen als Nächstes möglich sind, und in einer Formelspalte auch, welche Ergebnistypen unter <em>Ergebnis anzeigen als</em> zur Auswahl stehen.</p><div class="warning custom-block"><p class="custom-block-title">Ein leeres Beispielergebnis ist kein Beweis</p><p>Das Beispielergebnis wird <strong>im Browser</strong> berechnet, die produktive Auswertung läuft auf dem Server. Beides ist nicht deckungsgleich: Eine Reihe von Funktionen bleibt in der Vorschau leer, obwohl dieselbe Formel im Betrieb rechnet.</p><table tabindex="0"><thead><tr><th>Ausdruck</th><th>Vorschau</th><th>In der Formelspalte</th></tr></thead><tbody><tr><td><code>(100 / 3).round(2)</code></td><td>leer</td><td><code>33.33</code></td></tr><tr><td><code>today().addDays(1)</code></td><td>leer</td><td>das Datum von morgen</td></tr><tr><td><code>3.asString()</code></td><td>leer</td><td><code>3</code></td></tr><tr><td><code>&#39;a,b,c&#39;.match(&#39;[a-z]&#39;)</code></td><td>leer</td><td>rechnet</td></tr></tbody></table><p>Betroffen sind vor allem <strong>Datumsrechnungen</strong>, das <strong>Runden</strong> und einige <strong>Umwandlungen</strong> — und damit auch die relativen Datumsfilter der Oberfläche, die genau solche Ausdrücke sind.</p><p>Verlassen Sie sich deshalb auf die <strong>Typanzeige</strong> und prüfen Sie das Ergebnis an einem echten Eintrag beziehungsweise in einem Testlauf. Umgekehrt gilt aber: Ein Ausdruck, der in der Vorschau ein Ergebnis zeigt, ist auch produktiv in Ordnung.</p></div><h2 id="ubernehmen-und-fehler" tabindex="-1">Übernehmen und Fehler <a class="header-anchor" href="#ubernehmen-und-fehler" aria-label="Permalink to &quot;Übernehmen und Fehler&quot;">​</a></h2><p>Der Ausdruck wird übernommen, wenn Sie das Feld verlassen oder Enter drücken. Ist er nicht lesbar, erscheint die Meldung unter dem Feld — und der eingegebene Text bleibt als Text stehen, statt in Bausteine umgewandelt zu werden.</p><p><strong>Bausteine statt Text sind also die Bestätigung, dass der Ausdruck gelesen werden konnte.</strong> Bleibt Ihre Eingabe unverändert stehen, stimmt etwas nicht.</p><p>Die Meldungen sind englisch und nennen interne Typnamen; welche es gibt und was sie bedeuten, steht unter <a href="/apptivescript/schreibweise#fehlermeldungen-des-editors">Schreibweise</a>.</p><h2 id="grid-felder-im-html-block-und-im-javascript-schritt" tabindex="-1">Grid-Felder im HTML-Block und im JavaScript-Schritt <a class="header-anchor" href="#grid-felder-im-html-block-und-im-javascript-schritt" aria-label="Permalink to &quot;Grid-Felder im HTML-Block und im JavaScript-Schritt&quot;">​</a></h2><p>Der <a href="/seiten/html-bloecke">HTML-Block</a> und der Flow-Schritt <strong>JavaScript</strong> haben keinen Ausdruckseditor, sondern einen Code-Editor. Auch dort lassen sich Grid-Felder einfügen:</p><blockquote><p><em>Drücken Sie Strg + Leertaste um Grid-Felder einzufügen</em></p></blockquote><p>Die Vorschlagsliste zeigt die Feldnamen und fügt <code>{{fieldValue(&#39;&lt;Feld-Id&gt;&#39;)}}</code> ein — mit geschweiften Klammern, weil in diesen Editoren Text und Ausdruck gemischt werden. Dieselbe Liste erscheint, sobald Sie <code>field</code> tippen.</p><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/apptivescript/bedingungen">Bedingungen bauen</a> — Vergleiche, UND/ODER, Verzweigungen</li><li><a href="/apptivescript/werte-referenzieren">Werte referenzieren</a> — womit ein Ausdruck anfängt</li><li><a href="/referenz/apptivescript-funktionen">Funktionsreferenz</a> — alle Funktionen je Typ</li><li><a href="/grids/berechnete-felder">Berechnete Felder</a> · <a href="/flows/daten-zwischen-schritten">Daten zwischen Schritten</a></li></ul>',29)])])}const b=t(d,[["render",s]]);export{g as __pageData,b as default};
